    fun writeSliceString(w: AsukaNativeWriter, v: List<String>) {
        w.len(v.size)
        for (e in v) w.string(e)
    }

    fun readSliceString(r: AsukaNativeReader): List<String> {
        val n = r.len()
        return List(n) { r.string() }
    }

    fun writeAnchor(w: AsukaNativeWriter, v: Anchor) {
        w.float64(v.x)
        w.float64(v.y)
    }

    fun readAnchor(r: AsukaNativeReader): Anchor {
        val f0 = r.float64()
        val f1 = r.float64()
        return Anchor(x = f0, y = f1)
    }

    fun writeSliceSliceCoordinate(w: AsukaNativeWriter, v: List<List<Coordinate>>) {
        w.len(v.size)
        for (e in v) Wire.writeSliceCoordinate(w, e)
    }

    fun readSliceSliceCoordinate(r: AsukaNativeReader): List<List<Coordinate>> {
        val n = r.len()
        return List(n) { Wire.readSliceCoordinate(r) }
    }

}
